def num_comm_div(a, b):
    while b:
        a, b = b, a % b
    return a

def num_comm_div(num1, num2):
    common_divisors = []
    for i in range(1, min(num1, num2) + 1):
        if num1 % i == 0 and num2 % i == 0:
            common_divisors.append(i)
    return common_divisors[-1]

def num_comm_div(a, b):
    if a < b:
        a, b = b, a
    divisors = []
    for i in range(1, b+1):
        if a % i == 0 and b % i == 0:
            divisors.append(i)
    return divisors[-1]

def num_comm_div(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    return gcd(a, b)
